-- Fictional identities only. All application and identity writes roll back.
begin;
insert into auth.users(id,email,email_confirmed_at) select ('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,'study-'||n||'@example.invalid',now()-interval '1 day' from unnest(array[101,103,105,107])n;
insert into auth.sessions(id,user_id,created_at) select ('aaaaaaaa-aaaa-4aaa-8aaa-'||lpad(n::text,12,'0'))::uuid,('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,now()-interval '1 hour' from unnest(array[101,103,105,107])n;
insert into app_private.account_links(member_id,auth_user_id,username) select ('44444444-4444-4444-8444-'||lpad(n::text,12,'0'))::uuid,('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,'study_'||n from unnest(array[101,103,105,107])n;
create function pg_temp.login(n integer) returns void language plpgsql as $$begin
 perform set_config('request.jwt.claim.sub','99999999-9999-4999-8999-'||lpad(n::text,12,'0'),true);
 perform set_config('request.jwt.claims',jsonb_build_object('session_id','aaaaaaaa-aaaa-4aaa-8aaa-'||lpad(n::text,12,'0'))::text,true);
end $$;
create function pg_temp.pass(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'STUDY PASS: %',label;end $$;
create function pg_temp.denied(stmt text,expected text,label text) returns void language plpgsql as $$declare actual text;begin begin execute stmt;exception when others then get stacked diagnostics actual=returned_sqlstate;end;if actual is distinct from expected then raise exception 'FAIL: % expected % got %',label,expected,actual;end if;raise notice 'STUDY PASS: %',label;end $$;
create function pg_temp.tomorrow() returns date language sql stable as $$select (now() at time zone 'America/Los_Angeles')::date+1$$;
create function pg_temp.command(req uuid,resource integer,s integer,e integer) returns jsonb language sql stable as $$select jsonb_build_object('requestId',req,'action','reserve','resourceId','92000000-0000-4000-8000-'||lpad(resource::text,12,'0'),'day',pg_temp.tomorrow()::text,'start',s,'end',e,'purpose','contact','detail','Private Example Contact')$$;
update app_private.app_modules set status='approved',approved_at=now() where module_key='study-rooms';
insert into app_private.module_access_grants(member_id,module_id,permission,granted_at,reason) select ('44444444-4444-4444-8444-'||lpad(n::text,12,'0'))::uuid,'91000000-0000-4000-8000-000000000001',case n when 101 then 'manager' else 'viewer' end,now()-interval '1 day','Fictional study-module test grant' from unnest(array[101,103,107])n;
select pg_temp.login(107);set local role authenticated;
select set_config('test.booking',(public.study_room_command(pg_temp.command('97000000-0000-4000-8000-000000000001',1,780,840))->>'bookingId'),true);
select public.study_room_command(pg_temp.command('97000000-0000-4000-8000-000000000002',2,780,840));
create function pg_temp.change(req integer,res integer,s integer,e integer,v integer default 1) returns jsonb language sql stable as $$select pg_temp.command(('97000000-0000-4000-8000-'||lpad(req::text,12,'0'))::uuid,res,s,e)||jsonb_build_object('action','reschedule','bookingId',current_setting('test.booking'),'expectedVersion',v,'reason','Fictional schedule change')$$;
select pg_temp.denied('select app_private.study_room_command_r1(''{}'')','42501','legacy boundary cannot be bypassed');
select pg_temp.denied('select app_private.study_clock()','42501','clock is not a browser test-time override');
select pg_temp.denied('select public.study_room_admin()','42501','member cannot read private admin config');
select pg_temp.denied('select * from app_private.study_change_history','42501','direct history read denied');
select pg_temp.denied('select public.study_room_command(pg_temp.change(3,2,780,840))','23505','failed move preserves original booking');
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_schedule(pg_temp.tomorrow())->'bookings')x where x->>'id'=current_setting('test.booking') and x->>'resourceId'='92000000-0000-4000-8000-000000000001'),'original resource survives failed move');
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_schedule(pg_temp.tomorrow())->'bookings')x where x->>'id'=current_setting('test.booking') and x->>'version'='1'),'failed move does not advance version');
select pg_temp.pass(jsonb_array_length(public.member_module_home()->'activities')=2,'failed move does not duplicate activities');
reset role;select pg_temp.login(103);set local role authenticated;
select pg_temp.denied('select public.study_room_command(pg_temp.change(4,3,780,840))','42501','another group cannot reschedule the booking');
reset role;select pg_temp.login(107);set local role authenticated;
select pg_temp.pass(public.study_room_command(pg_temp.change(5,3,780,840))->>'version'='2','reschedule preserves identity and advances version');
select pg_temp.pass(public.study_room_command(pg_temp.change(5,3,780,840))->>'version'='2','successful move retry returns original receipt');
select pg_temp.denied('select public.study_room_command(pg_temp.change(5,4,780,840))','22023','same request ID cannot change payload');
select pg_temp.denied('select public.study_room_command(pg_temp.change(6,4,780,840))','40001','stale editor cannot overwrite moved booking');
select pg_temp.denied($q$select public.study_room_command(jsonb_build_object('requestId',gen_random_uuid(),'action','cancel','bookingId',current_setting('test.booking'),'expectedVersion',1,'reason','Stale screen cancellation'))$q$,'40001','stale cancellation cannot cancel changed reservation');
select pg_temp.pass(not(public.member_module_home()::text like '%Private Example Contact%'),'changed purpose details still absent from home feed');
reset role;
select pg_temp.pass((select count(*)=0 from app_private.study_slots where resource_id='92000000-0000-4000-8000-000000000001'),'successful move releases original resource');
select pg_temp.pass((select count(*)=2 from app_private.study_slots where booking_id=current_setting('test.booking')::uuid),'new resource has exact slot claims');
select pg_temp.pass((select count(*)=1 from app_private.study_change_history where target_id=current_setting('test.booking')::uuid),'move creates one history revision');
-- Replace ONLY the private clock function in this rollback transaction. Requests cannot do this.
create or replace function app_private.study_clock() returns timestamptz language sql volatile set search_path='' as $$select (((now() at time zone 'America/Los_Angeles')::date+1)+time '13:15') at time zone 'America/Los_Angeles'$$;
select pg_temp.login(107);set local role authenticated;
select pg_temp.denied('select public.study_room_command(pg_temp.change(7,4,840,870,2))','22023','running booking cannot be moved retrospectively');
select set_config('test.endcommand',jsonb_build_object('requestId','97000000-0000-4000-8000-000000000008','action','end_early','bookingId',current_setting('test.booking'),'expectedVersion',2,'reason','Fictional study completed')::text,true);
select pg_temp.pass(public.study_room_command(current_setting('test.endcommand')::jsonb)->>'releasedFrom'='810','early end uses server clock and next half-hour boundary');
select pg_temp.pass(public.study_room_command(current_setting('test.endcommand')::jsonb)->>'version'='3','early-end retry is idempotent');
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_schedule(pg_temp.tomorrow())->'bookings')b where b->>'id'=current_setting('test.booking') and b->>'state'='ended' and b->>'originalEnd'='840' and b->>'end'='810'),'original scheduled end retained with actual release boundary');
select pg_temp.pass(jsonb_array_length(public.member_module_home()->'activities')=1,'ended reservation removed from upcoming feed');
reset role;
select pg_temp.pass((select count(*)=1 from app_private.study_slots where booking_id=current_setting('test.booking')::uuid and minute=780),'elapsed/current slot is retained');
select pg_temp.pass((select count(*)=0 from app_private.study_slots where booking_id=current_setting('test.booking')::uuid and minute>=810),'only remaining slots freed');
select pg_temp.pass((select count(*)=2 from app_private.study_change_history where target_id=current_setting('test.booking')::uuid),'both move and early release history retained');
select pg_temp.login(101);set local role authenticated;
select pg_temp.pass(jsonb_array_length(public.study_room_admin()->'resources')=12,'explicit manager reads resource config');
select pg_temp.denied($q$select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','resource.update','resourceId','92000000-0000-4000-8000-000000000002','name','Room 2','active',false,'expectedVersion',1,'reason','Fictional close attempt'))$q$,'23505','cannot disable a booked resource');
select pg_temp.denied($q$select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','resource.update','resourceId','92000000-0000-4000-8000-000000000003','name','Room 3','active',false,'expectedVersion',1,'reason','Current slot still occupied'))$q$,'23505','early end does not free current half hour prematurely');
select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','resource.update','resourceId','92000000-0000-4000-8000-000000000004','name','Quiet Room 4','active',false,'expectedVersion',1,'reason','Fictional maintenance window'));
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_admin()->'resources')r where r->>'name'='Quiet Room 4' and r->>'active'='false' and r->>'version'='2'),'resource rename and deactivation persisted');
select pg_temp.denied($q$select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','resource.update','resourceId','92000000-0000-4000-8000-000000000004','name','Room 4','active',true,'expectedVersion',1,'reason','Stale configuration attempt'))$q$,'40001','stale manager cannot overwrite resource changes');
select pg_temp.denied($q$select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','closure.add','day',pg_temp.tomorrow()::text,'start',810,'end',840,'reason','Global closure conflicts'))$q$,'23505','global closure refuses any booked resource');
select set_config('test.closure',(public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','closure.add','resourceId','92000000-0000-4000-8000-000000000003','day',pg_temp.tomorrow()::text,'start',810,'end',840,'reason','Private maintenance explanation'))->>'id'),true);
select pg_temp.pass(jsonb_array_length(public.study_room_admin()->'closures')=1,'manager can add a nonconflicting resource-specific closure');
reset role;select pg_temp.login(107);set local role authenticated;
select pg_temp.pass(not(public.study_room_schedule(pg_temp.tomorrow())::text like '%Private maintenance explanation%'),'closure reason is redacted for ordinary members');
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_schedule(pg_temp.tomorrow())->'blocks')x where x->>'resourceId'='92000000-0000-4000-8000-000000000003' and x->>'label'='Scheduled closure'),'member sees only generic closure interval');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),3,810,840))$q$,'23505','closure blocks a new reservation');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),4,810,840))$q$,'22023','disabled resource cannot be booked');
select pg_temp.denied($q$select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','closure.remove','id',current_setting('test.closure'),'expectedVersion',1,'reason','Unauthorized reopen'))$q$,'42501','ordinary member cannot reopen a closure');
reset role;select pg_temp.login(101);set local role authenticated;
select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','closure.remove','id',current_setting('test.closure'),'expectedVersion',1,'reason','Maintenance complete'));
select pg_temp.pass(jsonb_array_length(public.study_room_admin()->'closures')=0,'removed closure no longer appears active');
reset role;select pg_temp.login(107);set local role authenticated;
select public.study_room_command(pg_temp.command('97000000-0000-4000-8000-000000000009',3,810,840));
select pg_temp.pass(jsonb_array_length(public.member_module_home()->'activities')=2,'released and reopened interval can be booked again');
reset role;
select pg_temp.pass((select count(*)=1 from app_private.study_closures where not active and version=2),'removed closure record kept for history');
select pg_temp.pass((select count(*)=2 from pg_tables where schemaname='app_private' and tablename in ('study_closures','study_change_history') and rowsecurity),'R2 private tables are RLS protected');
rollback;
